func generateReceiveLog(msg string) string {
	// BEGIN SOLUTION
	// sanitize msg so that it does not contain newline or carriage return characters
	var sanitizedMsg []rune
	for _, ch := range msg {
		if ch == '\n' || ch == '\r' {
